#define GPIOB_MODE_R 	 	(*(volatile unsigned int *)(GPIOB_BASE + MODE_R_OFFSET))
#define OD_R_OFFSET         (0x14UL)
#define GPIOB_OD_R 		    (*(volatile unsigned int *)(GPIOB_BASE + OD_R_OFFSET))
#define GPIOBEN    			(1U << 1)
#define PIN0       			(1U << 0)
